CREATE TABLE IF NOT EXISTS workspaces (id CHAR(36) PRIMARY KEY, name VARCHAR(120) NOT NULL, slug VARCHAR(80) NOT NULL UNIQUE, timezone VARCHAR(80) NOT NULL DEFAULT 'UTC', currency CHAR(3) NOT NULL DEFAULT 'INR', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users (id CHAR(36) PRIMARY KEY, email VARCHAR(254) NOT NULL, email_normalized VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, display_name VARCHAR(120) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS workspace_memberships (id CHAR(36) PRIMARY KEY, workspace_id CHAR(36) NOT NULL, user_id CHAR(36) NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE', joined_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_membership (workspace_id,user_id), FOREIGN KEY (workspace_id) REFERENCES workspaces(id), FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS roles (id CHAR(36) PRIMARY KEY, `key` VARCHAR(60) NOT NULL UNIQUE, name VARCHAR(80) NOT NULL);
CREATE TABLE IF NOT EXISTS membership_roles (membership_id CHAR(36) NOT NULL, role_id CHAR(36) NOT NULL, PRIMARY KEY(membership_id,role_id), FOREIGN KEY(membership_id) REFERENCES workspace_memberships(id), FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE IF NOT EXISTS categories (id CHAR(36) PRIMARY KEY, workspace_id CHAR(36) NOT NULL, name VARCHAR(80) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_category(workspace_id,name), FOREIGN KEY(workspace_id) REFERENCES workspaces(id));
CREATE TABLE IF NOT EXISTS suppliers (id CHAR(36) PRIMARY KEY, workspace_id CHAR(36) NOT NULL, name VARCHAR(160) NOT NULL, contact_name VARCHAR(120), contact_email VARCHAR(254), phone VARCHAR(40), lead_time_days INT NOT NULL DEFAULT 0, status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_supplier(workspace_id,name), FOREIGN KEY(workspace_id) REFERENCES workspaces(id));
CREATE TABLE IF NOT EXISTS products (id CHAR(36) PRIMARY KEY, workspace_id CHAR(36) NOT NULL, category_id CHAR(36) NOT NULL, supplier_id CHAR(36), sku VARCHAR(80) NOT NULL, name VARCHAR(160) NOT NULL, description TEXT, unit_price DECIMAL(12,2) NOT NULL DEFAULT 0, currency CHAR(3) NOT NULL DEFAULT 'INR', reorder_point INT NOT NULL DEFAULT 0, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_sku(workspace_id,sku), INDEX ix_product_name(workspace_id,name), FOREIGN KEY(workspace_id) REFERENCES workspaces(id), FOREIGN KEY(category_id) REFERENCES categories(id), FOREIGN KEY(supplier_id) REFERENCES suppliers(id));
CREATE TABLE IF NOT EXISTS inventory_balances (id CHAR(36) PRIMARY KEY, workspace_id CHAR(36) NOT NULL, product_id CHAR(36) NOT NULL UNIQUE, on_hand INT NOT NULL DEFAULT 0, reserved INT NOT NULL DEFAULT 0, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CHECK(on_hand>=0), CHECK(reserved>=0), FOREIGN KEY(workspace_id) REFERENCES workspaces(id), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS expiry_batches (id CHAR(36) PRIMARY KEY, workspace_id CHAR(36) NOT NULL, product_id CHAR(36) NOT NULL, purchase_line_id CHAR(36), batch_number VARCHAR(100) NOT NULL, received_at DATE NOT NULL, expires_at DATE NOT NULL, quantity_received INT NOT NULL, quantity_available INT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_batch(workspace_id,product_id,batch_number), INDEX ix_expiry(workspace_id,expires_at), CHECK(expires_at>received_at), CHECK(quantity_available>=0), FOREIGN KEY(workspace_id) REFERENCES workspaces(id), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS stock_movements (id CHAR(36) PRIMARY KEY, workspace_id CHAR(36) NOT NULL, product_id CHAR(36) NOT NULL, batch_id CHAR(36), type VARCHAR(24) NOT NULL, quantity_delta INT NOT NULL, reference_type VARCHAR(40), reference_id CHAR(36), reason VARCHAR(500), actor_user_id CHAR(36), idempotency_key VARCHAR(120), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_idempotency(workspace_id,idempotency_key), INDEX ix_movement(workspace_id,created_at), FOREIGN KEY(workspace_id) REFERENCES workspaces(id), FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(batch_id) REFERENCES expiry_batches(id), FOREIGN KEY(actor_user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS purchase_orders (id CHAR(36) PRIMARY KEY, workspace_id CHAR(36) NOT NULL, supplier_id CHAR(36) NOT NULL, order_number VARCHAR(40) NOT NULL, status VARCHAR(24) NOT NULL DEFAULT 'DRAFT', currency CHAR(3) NOT NULL DEFAULT 'INR', expected_at DATE, notes VARCHAR(1000), created_by CHAR(36), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_order(workspace_id,order_number), FOREIGN KEY(workspace_id) REFERENCES workspaces(id), FOREIGN KEY(supplier_id) REFERENCES suppliers(id), FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS purchase_order_lines (id CHAR(36) PRIMARY KEY, workspace_id CHAR(36) NOT NULL, purchase_order_id CHAR(36) NOT NULL, product_id CHAR(36) NOT NULL, quantity_ordered INT NOT NULL, quantity_received INT NOT NULL DEFAULT 0, unit_cost DECIMAL(12,2) NOT NULL, CHECK(quantity_ordered>0), CHECK(quantity_received>=0 AND quantity_received<=quantity_ordered), CHECK(unit_cost>=0), FOREIGN KEY(workspace_id) REFERENCES workspaces(id), FOREIGN KEY(purchase_order_id) REFERENCES purchase_orders(id), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS notifications (id CHAR(36) PRIMARY KEY, workspace_id CHAR(36) NOT NULL, recipient_user_id CHAR(36) NOT NULL, type VARCHAR(40) NOT NULL, title VARCHAR(160) NOT NULL, message VARCHAR(500) NOT NULL, entity_type VARCHAR(40), entity_id CHAR(36), dedupe_key VARCHAR(160), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, read_at TIMESTAMP NULL, INDEX ix_notifications(recipient_user_id,read_at,created_at), UNIQUE KEY uq_notification_dedupe(workspace_id,recipient_user_id,dedupe_key), FOREIGN KEY(workspace_id) REFERENCES workspaces(id), FOREIGN KEY(recipient_user_id) REFERENCES users(id));
